// Вход: {severity, title, text, data}. Выход: запись о доставке в тестовый канал.
return $input.all().map(item => ({
  json: {
    channel: 'test',
    delivered_at: new Date().toISOString(),
    severity: item.json.severity || 'info',
    title: item.json.title || 'Stocker',
    text: item.json.text || '',
    data: item.json.data || null,
  },
}));
